UT: [C001] a consolidation emits manifest stubs[].file as a cwd-relative path (no leading /, no '..')
  const res = runBatchUpdate({ decision: [{ unitId: 'U1', resolveByTicket: 'P4-2', markerLines: ['src/a.rs:4'] }], dir: ws.dir, ticketsPath: ws.ticketsPath });
  const manifest = JSON.parse(fs.readFileSync(res.manifestPath, 'utf8'));
