    { relation: 'same_commit', target: 'ev-impl-31', confidence: 'medium', basis: ['git:a1b2c3d'] },
  ]);

  // strong and medium both collapse; the count is components, never records.
  assert.equal(countIndependentSupport([implementationEvidence, testEvidence]), 1);
  assert.equal(countIndependentSupport([implementationEvidence, readmeEvidence]), 1);

