  const folded = computeIndependence([implementationEvidence, testEvidence, readmeEvidence]);
  assert.ok(
    folded.independentCount < folded.evidence.length,
    'the independent group count is strictly less than the raw evidence count',
  );

  // What the text cannot settle is recorded as unknown, never defaulted to independent.
  assert.equal(computeIndependence([implementationEvidence, readmeEvidence], { root: null }).evidence[1].independence_assessment, 'unknown');
});
