  const touched = after.claims.find((claim) => claim.claim_id === counterexample.claim_id);
  assert.ok(['retracted', 'split'].includes(touched.revision), `expected retracted or split, got ${touched.revision}`);
  assert.equal(touched.revised_by, counterexample.counterexample_plan_id);

  const untouched = after.claims.filter((claim) => claim.claim_id !== counterexample.claim_id);
  assert.ok(untouched.every((claim) => claim.revision === undefined), 'a counterexample reaches only the claim it bears on');
  assert.equal(after.claims.length, ledger.claims.length + (touched.revision === 'split' ? 1 : 0));
  assert.deepEqual(after.revisions, [
    { claim_id: counterexample.claim_id, revision: touched.revision, counterexample_plan_id: counterexample.counterexample_plan_id, counterexample: { observed: 'red', observation: counterexample.observation } },
  ]);
});
```

UT-C003-inv: [C003 invariant] "a red failure is never automatically concluded to be a specification error" — invariant predicate over the emitted record
```js
test('C003 invariant: the output carries the counterexample and leaves the verdict open', () => {
  const after = applyCounterexample(counterexample, ledger);
  const serialised = JSON.stringify(after);

  for (const verdict of ['specification_error', 'spec_error', 'bug_confirmed', 'implementation_wrong', 'contract_violated']) {
    assert.ok(!serialised.includes(verdict), `the ledger must not assert ${verdict}`);
  }
  assert.equal(after.verdict, null);
  assert.equal(Object.hasOwn(after, 'verdict_set_by'), false);
  assert.deepEqual(after.revisions[0].counterexample, {
    observed: 'red',
    observation: counterexample.observation,
  });
});
